def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 140:
                rich_opp += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive:
        return max(0.0, min(float(budget), 18.0 if hp > 3 else 40.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (25.0 - supply) / 10.0
    danger = 0.0
    if hp <= 2:
        danger += 1.0
    elif hp <= 4:
        danger += 0.55
    if no_water >= 2:
        danger += 1.0
    elif no_water >= 1:
        danger += 0.45

    market_pressure = 0.0
    if highest_prev >= 180:
        market_pressure = 1.0
    elif highest_prev >= 140:
        market_pressure = 0.75
    elif highest_prev >= 100:
        market_pressure = 0.45
    else:
        market_pressure = 0.2

    if supply <= 16:
        base = 78 + 18 * danger + 10 * market_pressure + 4 * rich_opp
    elif supply <= 18:
        base = 60 + 16 * danger + 8 * market_pressure + 3 * urgent_opp
    elif supply <= 21:
        base = 43 + 13 * danger + 6 * market_pressure
    else:
        base = 28 + 10 * danger + 4 * market_pressure

    if hp >= 7 and no_water == 0 and supply >= 20 and highest_prev >= 130:
        base *= 0.72

    if day >= 8:
        base += 8 + 6 * danger

    target = max(base, avg_prev * 0.92)

    if danger >= 1.0:
        target = max(target, highest_prev + 3.0)
    elif danger >= 0.45 and supply <= 18:
        target = max(target, highest_prev + 1.5)
    else:
        if highest_prev >= 150:
            target = min(target, highest_prev - 8.0)

    if budget < 90:
        target = min(target, budget * (0.72 if danger < 1.0 else 0.9))

    floor_bid = 8.0
    if danger >= 1.0:
        floor_bid = 35.0
    elif supply <= 17:
        floor_bid = 24.0

    bid = max(floor_bid, target)
    bid = min(float(budget), bid)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    water_need = my_status['hp'] < WATER_REQ * 2
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        base_bid = min(DAILY_SALARY * 1.3, max_prev + 2.0)
    else:
        base_bid = DAILY_SALARY * 0.8

    if my_status['hp'] <= 3:
        # desperate
        bid = min(my_status['budget'], base_bid * 1.3 + 5)
    elif my_status['hp'] >= 8:
        # safe
        bid = min(my_status['budget'], base_bid * 0.6)
    else:
        bid = min(my_status['budget'], base_bid)

    # Ensure bid is positive and within budget
    bid = max(1, min(my_status['budget'], bid))
    return float(bid)
